1	using System.Diagnostics;
2	using System.Text;
3	using Microsoft.Xna.Framework;
4	using Microsoft.Xna.Framework.Graphics;
5	using SixLabors.ImageSharp;
6	using SixLabors.ImageSharp.PixelFormats;
7	using BetterArc.Gameplay;
8	using BetterArc.Render;
9	using Color = Microsoft.Xna.Framework.Color;
10	
11	namespace BetterArc.Tests.Visual;
12	
13	public abstract class VisualTestBase
14	{
15	    protected abstract string ChartName { get; }
16	    protected abstract string ChartPath { get; }
17	    protected abstract float SsimThreshold { get; }
18	
19	    protected int Width => 1280;
20	    protected int Height => 720;
21	
22	    protected void RunVisualComparison()
23	    {
24	        string? refDir = FindReferenceDir();
25	        if (refDir == null || !Directory.Exists(refDir))
26	        {
27	            return;
28	        }
29	
30	        var timePoints = ScanReferenceFrames(refDir);
31	        if (timePoints.Count == 0)
32	        {
33	            return;
34	        }
35	
36	        string chartFullPath = FindChartFile();
37	        string chartText = File.ReadAllText(chartFullPath);
38	        string outputDir = GetOutputDir();
39	        Directory.CreateDirectory(outputDir);
40	
41	        Console.Error.WriteLine($"[L2] Rendering {timePoints.Count} frames at {Width}x{Height}...");
42	        var sw = Stopwatch.StartNew();
43	
44	        var renderGame = new RenderBatchGame(
45	            Width, Height, chartText, timePoints, outputDir);
46	
47	        try
48	        {
49	            renderGame.Run();
50	        }
51	        catch (NoSuitableGraphicsDeviceException)
52	        {
53	            return;
54	        }
55	
56	        Console.Error.WriteLine($"[L2] Rendering done in {sw.Elapsed.TotalSeconds:F1}s. Comparing...");
57	
58	        var results = new List<FrameResult>();
59	        for (int i = 0; i < timePoints.Count; i++)
60	        {
61	            var (timeMs, refPath) = timePoints[i];
62	            string actualPath = Path.Combine(outputDir, $"actual_t{FormatTime(timeMs)}.png");
63	            if (!File.Exists(actualPath)) continue;
64	
65	            string diffPath = Path.Combine(outputDir, $"diff_t{FormatTime(timeMs)}.png");
66	            float ssim = ImageComparer.GenerateDiff(refPath, actualPath, diffPath);
67	            results.Add(new FrameResult(timeMs, ssim, diffPath));
68	
69	            if ((i + 1) % 20 == 0 || i + 1 == timePoints.Count)
70	                Console.Error.WriteLine($"[L2] Diff {i + 1}/{timePoints.Count} (t{FormatTime(timeMs)} SSIM={ssim:F4})");
71	        }
72	
73	        Console.Error.WriteLine($"[L2] All comparisons done in {sw.Elapsed.TotalSeconds:F1}s.");
74	
75	        string reportPath = Path.Combine(outputDir, "report.txt");
76	        WriteReport(reportPath, results);
77	
78	        var failed = results.Where(r => r.Ssim < SsimThreshold).ToList();
79	        if (failed.Count > 0)
80	        {
81	            var worst = failed.OrderBy(r => r.Ssim).First();
82	            Assert.Fail(
83	                $"L2 visual comparison failed: {failed.Count}/{results.Count} frames below threshold ({SsimThreshold:F2}).\n" +
84	                $"Worst: t{FormatTime(worst.TimeMs)} SSIM={worst.Ssim:F4}\n" +
85	                $"Report: {reportPath}");
86	        }
87	    }
88	
89	    private string? FindReferenceDir()
90	    {
91	        string[] candidates =
92	        {
93	            Path.Combine(AppContext.BaseDirectory, "TestData", "L2", ChartName),
94	            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "TestData", "L2", ChartName),
95	        };
96	        foreach (var c in candidates)
97	        {
98	            string resolved = Path.GetFullPath(c);
99	            if (Directory.Exists(resolved)) return resolved;
100	        }
101	        return null;
102	    }
103	
104	    private string FindChartFile()
105	    {
106	        string[] candidates =
107	        {
108	            Path.Combine(AppContext.BaseDirectory, ChartPath),
109	            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", ChartPath),
110	        };
111	        foreach (var c in candidates)
112	        {
113	            string resolved = Path.GetFullPath(c);
114	            if (File.Exists(resolved)) return resolved;
115	        }
116	        throw new FileNotFoundException($"Chart file not found: {ChartPath}");
117	    }
118	
119	    internal static List<(int timeMs, string path)> ScanReferenceFrames(string dir)
120	    {
121	        var results = new List<(int, string)>();
122	
123	        foreach (var file in Directory.GetFiles(dir, "t*.png"))
124	        {
125	            string name = Path.GetFileNameWithoutExtension(file);
126	            if (TryParseTime(name, out int timeMs))
127	                results.Add((timeMs, file));
128	        }
129	
130	        results.Sort((a, b) => a.Item1.CompareTo(b.Item1));
131	        return results;
132	    }
133	
134	    internal static bool TryParseTime(string name, out int timeMs)
135	    {
136	        timeMs = 0;
137	        if (name.Length < 2 || name[0] != 't') return false;
138	        return int.TryParse(name.Substring(1), out timeMs);
139	    }
140	
141	    internal static string FormatTime(int timeMs)
142	    {
143	        if (timeMs < 0)
144	            return $"-{(-timeMs):D5}";
145	        return $"{timeMs:D5}";
146	    }
147	
148	    private string GetOutputDir()
149	    {
150	        string baseDir = Path.Combine(
151	            AppContext.BaseDirectory, "..", "..", "..", "..", "TestResults", "L2", ChartName);
152	        return Path.GetFullPath(baseDir);
153	    }
154	
155	    private void WriteReport(string path, List<FrameResult> results)
156	    {
157	        var sb = new StringBuilder();
158	        sb.AppendLine($"Chart: {ChartName}");
159	        sb.AppendLine($"Threshold: {SsimThreshold:F2}");
160	
161	        int passed = results.Count(r => r.Ssim >= SsimThreshold);
162	        int failed = results.Count - passed;
163	        sb.AppendLine($"Frames: {results.Count} total, {passed} passed, {failed} failed");
164	        sb.AppendLine();
165	
166	        var failedFrames = results.Where(r => r.Ssim < SsimThreshold)
167	            .OrderBy(r => r.Ssim).ToList();
168	        if (failedFrames.Count > 0)
169	        {
170	            sb.AppendLine("FAILED FRAMES:");
171	            foreach (var f in failedFrames)
172	                sb.AppendLine($"  t{FormatTime(f.TimeMs)}  SSIM={f.Ssim:F4}  diff: {Path.GetFileName(f.DiffPath)}");
173	            sb.AppendLine();
174	        }
175	
176	        var worstPassed = results.Where(r => r.Ssim >= SsimThreshold)
177	            .OrderBy(r => r.Ssim).Take(5).ToList();
178	        if (worstPassed.Count > 0)
179	        {
180	            sb.AppendLine("PASSED FRAMES (worst 5):");
181	            foreach (var f in worstPassed)
182	                sb.AppendLine($"  t{FormatTime(f.TimeMs)}  SSIM={f.Ssim:F4}");
183	        }
184	
185	        File.WriteAllText(path, sb.ToString());
186	    }
187	
188	    private record FrameResult(int TimeMs, float Ssim, string DiffPath);
189	}
190	
191	internal class RenderBatchGame : Game
192	{
193	    private readonly GraphicsDeviceManager _graphics;
194	    private readonly string _chartText;
195	    private readonly List<(int timeMs, string refPath)> _timePoints;
196	    private readonly string _outputDir;
197	
198	    private CameraService? _camera;
199	    private TextureService? _textures;
200	    private TrackRenderer? _track;
201	    private NoteRenderer? _notes;
202	    private GameplayService? _gameplay;
203	    private RenderTarget2D? _renderTarget;
204	    private Color[]? _pixelBuffer;
205	    private int _frameIndex;
206	    private long _renderTicks, _readbackTicks, _encodeTicks;
207	
208	    public RenderBatchGame(
209	        int width, int height, string chartText,
210	        List<(int timeMs, string refPath)> timePoints, string outputDir)
211	    {
212	        _chartText = chartText;
213	        _timePoints = timePoints;
214	        _outputDir = outputDir;
215	
216	        _graphics = new GraphicsDeviceManager(this)
217	        {
218	            PreferredBackBufferWidth = width,
219	            PreferredBackBufferHeight = height,
220	            GraphicsProfile = GraphicsProfile.HiDef,
221	            SynchronizeWithVerticalRetrace = false,
222	        };
223	
224	        IsMouseVisible = false;
225	        IsFixedTimeStep = false;
226	        TargetElapsedTime = TimeSpan.FromMilliseconds(1);
227	    }
228	
229	    protected override void Initialize()
230	    {
231	        _camera = new CameraService();
232	        _textures = new TextureService();
233	        _textures.Initialize(GraphicsDevice);
234	        _track = new TrackRenderer(GraphicsDevice);
235	        _notes = new NoteRenderer(GraphicsDevice);
236	        _gameplay = new GameplayService();
237	        _gameplay.LoadChart(_chartText);
238	
239	        int w = _graphics.PreferredBackBufferWidth;
240	        int h = _graphics.PreferredBackBufferHeight;
241	        _renderTarget = new RenderTarget2D(GraphicsDevice, w, h,
242	            false, SurfaceFormat.Color, DepthFormat.Depth24);
243	        _pixelBuffer = new Color[w * h];
244	
245	        base.Initialize();
246	    }
247	
248	    protected override void Draw(GameTime gameTime)
249	    {
250	        if (_frameIndex >= _timePoints.Count)
251	        {
252	            Exit();
253	            return;
254	        }
255	
256	        var (timeMs, _) = _timePoints[_frameIndex];
257	        _gameplay!.CurrentTiming = timeMs;
258	
259	        int w = _renderTarget!.Width;
260	        int h = _renderTarget.Height;
261	
262	        long t0 = Stopwatch.GetTimestamp();
263	
264	        GraphicsDevice.SetRenderTarget(_renderTarget);
265	        GraphicsDevice.Clear(Color.Black);
266	        _camera!.Update((float)w / h);
267	        _track!.Draw(_camera, _textures!, _gameplay);
268	        _notes!.Draw(_camera, _gameplay, _textures!);
269	        GraphicsDevice.SetRenderTarget(null);
270	
271	        long t1 = Stopwatch.GetTimestamp();
272	
273	        _renderTarget.GetData(_pixelBuffer);
274	
275	        long t2 = Stopwatch.GetTimestamp();
276	
277	        SavePng(_pixelBuffer!, w, h, Path.Combine(_outputDir,
278	            $"actual_t{VisualTestBase.FormatTime(timeMs)}.png"));
279	
280	        long t3 = Stopwatch.GetTimestamp();
281	
282	        _renderTicks += t1 - t0;
283	        _readbackTicks += t2 - t1;
284	        _encodeTicks += t3 - t2;
285	        _frameIndex++;
286	
287	        if (_frameIndex % 20 == 0 || _frameIndex == _timePoints.Count)
288	        {
289	            double renderMs = _renderTicks * 1000.0 / Stopwatch.Frequency;
290	            double readbackMs = _readbackTicks * 1000.0 / Stopwatch.Frequency;
291	            double encodeMs = _encodeTicks * 1000.0 / Stopwatch.Frequency;
292	            Console.Error.WriteLine(
293	                $"[L2] {_frameIndex}/{_timePoints.Count} (t={timeMs}ms) " +
294	                $"render={renderMs:F0}ms readback={readbackMs:F0}ms encode={encodeMs:F0}ms");
295	        }
296	
297	        if (_frameIndex >= _timePoints.Count)
298	            Exit();
299	
300	        base.Draw(gameTime);
301	    }
302	
303	    private static readonly SixLabors.ImageSharp.Formats.Png.PngEncoder FastPng = new()
304	    {
305	        CompressionLevel = SixLabors.ImageSharp.Formats.Png.PngCompressionLevel.BestSpeed,
306	    };
307	
308	    private static void SavePng(Color[] pixels, int w, int h, string path)
309	    {
310	        using var img = new Image<Rgba32>(w, h);
311	        for (int y = 0; y < h; y++)
312	        {
313	            var row = img.Frames.RootFrame.PixelBuffer.DangerousGetRowSpan(y);
314	            for (int x = 0; x < w; x++)
315	            {
316	                var c = pixels[y * w + x];
317	                row[x] = new Rgba32(c.R, c.G, c.B, c.A);
318	            }
319	        }
320	        img.Save(path, FastPng);
321	    }
322	
323	    protected override void Dispose(bool disposing)
324	    {
325	        _renderTarget?.Dispose();
326	        base.Dispose(disposing);
327	    }
328	}
