140	                float ay1 = ArcFormula.Y(arc.YStart, arc.YEnd, t1, arc.LineType);
141	
142	                float wx0 = ArcFormula.ArcXToWorld(ax0);
143	                float wy0 = ArcFormula.ArcYToWorld(ay0);
144	                float wx1 = ArcFormula.ArcXToWorld(ax1);
145	                float wy1 = ArcFormula.ArcYToWorld(ay1);
