using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using BetterArc.Gameplay;
using BetterArc.Gameplay.Data;

namespace BetterArc.Render;

public class NoteRenderer
{
    private readonly GraphicsDevice _device;
    private readonly BasicEffect _effect;

    private static readonly Color[] ArcColors =
    {
        new Color(0, 200, 255),
        new Color(255, 100, 200),
    };
    private static readonly Color TraceColor = new Color(180, 180, 180, 100);
    private static readonly Color ShadowColor = new Color(0, 0, 0, 120);

    public NoteRenderer(GraphicsDevice device)
    {
        _device = device;
        _effect = new BasicEffect(device)
        {
            VertexColorEnabled = true,
            TextureEnabled = true,
        };
    }

    public void Draw(CameraService camera, GameplayService gameplay, TextureService textures)
    {
        if (gameplay.Chart == null) return;

