using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using Microsoft.Xna.Framework.Input;
using BetterArc.Render;
using BetterArc.Input;
using BetterArc.Judgment;

namespace BetterArc;

public class BetterArcGame : Game
{
    private GraphicsDeviceManager _graphics;
    private SpriteBatch? _spriteBatch;
    private CameraService? _camera;
    private TextureService? _textures;
    private TrackRenderer? _track;
    private NoteRenderer? _notes;
    private Gameplay.GameplayService? _gameplay;
    private InputService? _input;
    private ScoreService? _score;
    private bool _autoPlay = true;
    private KeyboardState _prevKb;

    private readonly HashSet<int> _judgedTapTimings = new();
    private string _lastJudgment = "";
    private int _lastJudgmentTime;

    public BetterArcGame()
    {
        _graphics = new GraphicsDeviceManager(this);
        _graphics.PreferredBackBufferWidth = 1280;
        _graphics.PreferredBackBufferHeight = 720;
        Window.Title = "BetterArc v2";
        IsMouseVisible = true;
    }

    protected override void Initialize()
    {
        _camera = new CameraService();
        _textures = new TextureService();
        _textures.Initialize(GraphicsDevice);
        _track = new TrackRenderer(GraphicsDevice);
        _notes = new NoteRenderer(GraphicsDevice);
        _gameplay = new Gameplay.GameplayService();
        _input = new InputService();
        _score = new ScoreService();

        string chartPath = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "assets", "charts", "sayonarahatsukoi_ftr.aff");
        if (File.Exists(chartPath))
        {
            _gameplay.LoadChart(File.ReadAllText(chartPath));
            int totalNotes = _gameplay.Chart!.TimingGroups.Sum(
                tg => tg.Taps.Count + tg.Holds.Count + tg.Arcs.Count(a => !a.IsTrace));
            _score.SetNoteCount(totalNotes);
        }

        base.Initialize();
    }

    protected override void LoadContent()
    {
        _spriteBatch = new SpriteBatch(GraphicsDevice);
    }

    protected override void Update(GameTime gameTime)
    {
        var kb = Keyboard.GetState();
        _input!.Update();

        // Toggle auto-play with A key
        if (kb.IsKeyDown(Keys.A) && _prevKb.IsKeyUp(Keys.A))
            _autoPlay = !_autoPlay;

        // Timeline scrubbing
        int speed = kb.IsKeyDown(Keys.LeftShift) ? 100 : 20;
        if (kb.IsKeyDown(Keys.Right))
            _gameplay!.CurrentTiming += speed;
        if (kb.IsKeyDown(Keys.Left))
            _gameplay!.CurrentTiming = Math.Max(0, _gameplay.CurrentTiming - speed);
        if (kb.IsKeyDown(Keys.Space) && _prevKb.IsKeyUp(Keys.Space))
            _gameplay!.CurrentTiming = 0;

        // Judgment processing
        if (_gameplay!.Chart != null)
            ProcessJudgments();

        float aspect = GraphicsDevice.Viewport.AspectRatio;
        _camera!.Update(aspect);
        _prevKb = kb;

        base.Update(gameTime);
    }

    private void ProcessJudgments()
    {
        if (_gameplay?.Chart == null) return;

        for (int tg = 0; tg < _gameplay.Chart.TimingGroups.Count; tg++)
        {
            foreach (var tap in _gameplay.Chart.TimingGroups[tg].Taps)
            {
                int key = tap.Timing * 1000 + tg;
                if (_judgedTapTimings.Contains(key)) continue;

                int offset = _gameplay.CurrentTiming - tap.Timing;

                if (offset > Gameplay.Values.MissJudgeWindow)
                {
                    _judgedTapTimings.Add(key);
                    var result = JudgmentResult.MissLate;
                    _score!.ProcessResult(result);
                    ShowJudgment(result, offset);
                    continue;
                }

                if (_autoPlay && Math.Abs(offset) <= 5)
                {
                    _judgedTapTimings.Add(key);
                    _score!.ProcessResult(JudgmentResult.Max);
                    ShowJudgment(JudgmentResult.Max, 0);
                    continue;
                }

                if (!_autoPlay && JudgmentService.IsWithinWindow(offset))
                {
                    int lane = (int)Math.Round(tap.Lane);
                    if (_input!.IsLaneJustPressed(lane))
                    {
                        _judgedTapTimings.Add(key);
                        var result = JudgmentService.Judge(offset);
                        _score!.ProcessResult(result);
                        ShowJudgment(result, offset);
                    }
                }
            }
        }
    }

    private void ShowJudgment(JudgmentResult result, int offset)
    {
        string earlyLate = offset < 0 ? " EARLY" : offset > 0 ? " LATE" : "";
        _lastJudgment = result switch
        {
            JudgmentResult.Max => "PURE",
            JudgmentResult.PerfectEarly or JudgmentResult.PerfectLate => $"PURE{earlyLate}",
            JudgmentResult.GoodEarly or JudgmentResult.GoodLate => $"FAR{earlyLate}",
            _ => "LOST",
        };
        _lastJudgmentTime = _gameplay!.CurrentTiming;
    }

    protected override void Draw(GameTime gameTime)
    {
        GraphicsDevice.Clear(Color.Black);

        if (_camera != null && _track != null && _notes != null && _gameplay != null && _textures != null)
        {
            _track.Draw(_camera, _textures, _gameplay);
            _notes.Draw(_camera, _gameplay, _textures);
        }

        DrawHUD();
        base.Draw(gameTime);
    }

    private void DrawHUD()
    {
        if (_spriteBatch == null || _score == null || _gameplay == null) return;

        _spriteBatch.Begin();

        string mode = _autoPlay ? "[AUTO]" : "[D/F/J/K]";
        string hud = $"{mode}  Score: {_score.Score:N0}  Combo: {_score.CurrentCombo}  " +
                      $"Max:{_score.MaxCount} P:{_score.PerfectCount} G:{_score.GoodCount} M:{_score.MissCount}  " +
                      $"t={_gameplay.CurrentTiming}ms";

        // Draw judgment text (fade out after 500ms)
        if (_gameplay.CurrentTiming - _lastJudgmentTime < 500 && _lastJudgment.Length > 0)
        {
            hud += $"  [{_lastJudgment}]";
        }

        // Simple text rendering without SpriteFont - use Window title as HUD
        Window.Title = $"BetterArc v2 — {hud}";

        _spriteBatch.End();
    }

    public CameraService Camera => _camera!;
    public Gameplay.GameplayService GameplayService => _gameplay!;
}

using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using BetterArc.Gameplay;

namespace BetterArc.Render;

public class TrackRenderer
{
    private readonly GraphicsDevice _device;
    private readonly BasicEffect _effect;

    public TrackRenderer(GraphicsDevice device)
    {
        _device = device;
        _effect = new BasicEffect(device)
        {
            VertexColorEnabled = true,
            TextureEnabled = true,
        };
    }

    public void Draw(CameraService camera, TextureService textures, GameplayService? gameplay)
    {
        _effect.View = camera.View;
        _effect.Projection = camera.Projection;
        _effect.World = Matrix.Identity;

        _device.DepthStencilState = DepthStencilState.Default;
        _device.BlendState = BlendState.AlphaBlend;
        _device.RasterizerState = RasterizerState.CullNone;
        _device.SamplerStates[0] = SamplerState.LinearClamp;

        DrawTrackSurface(textures);
        DrawLaneDividers(textures);
        DrawCriticalLine(textures);
        if (gameplay != null)
            DrawBeatlines(textures, gameplay);
    }

    private void DrawTrackSurface(TextureService textures)
    {
        float left = ArcFormula.LaneToWorldX(4);
        float right = ArcFormula.LaneToWorldX(1);
        float far = -Values.TrackLengthForward;
        float near = Values.TrackLengthBackward;

        _effect.Texture = textures.Get("track");
        var color = new Color(180, 180, 200, 220);

        var verts = new VertexPositionColorTexture[]
        {
            new(new Vector3(left, 0, far), color, new Vector2(0, 0)),
            new(new Vector3(right, 0, far), color, new Vector2(1, 0)),
            new(new Vector3(right, 0, near), color, new Vector2(1, 1)),
            new(new Vector3(left, 0, near), color, new Vector2(0, 1)),
        };
        var indices = new short[] { 0, 1, 2, 0, 2, 3 };

        foreach (var pass in _effect.CurrentTechnique.Passes)
        {
            pass.Apply();
            _device.DrawUserIndexedPrimitives(PrimitiveType.TriangleList, verts, 0, 4, indices, 0, 2);
        }
    }

    private void DrawLaneDividers(TextureService textures)
    {
        _effect.Texture = textures.Has("trackDivider") ? textures.Get("trackDivider") : textures.White;
        Color lineColor = new Color(150, 150, 180, 120);
        float width = 0.06f;
        float far = -Values.TrackLengthForward;
        float near = Values.TrackLengthBackward;

        var allVerts = new List<VertexPositionColorTexture>();
        var allIndices = new List<short>();

        for (int lane = 1; lane <= 4; lane++)
        {
            float x = ArcFormula.LaneToWorldX(lane);
            short offset = (short)allVerts.Count;
            allVerts.Add(new(new Vector3(x - width, 0.01f, far), lineColor, new Vector2(0, 0)));
            allVerts.Add(new(new Vector3(x + width, 0.01f, far), lineColor, new Vector2(1, 0)));
            allVerts.Add(new(new Vector3(x + width, 0.01f, near), lineColor, new Vector2(1, 1)));
            allVerts.Add(new(new Vector3(x - width, 0.01f, near), lineColor, new Vector2(0, 1)));
            allIndices.AddRange(new short[] { offset, (short)(offset + 1), (short)(offset + 2), offset, (short)(offset + 2), (short)(offset + 3) });
        }

        foreach (var pass in _effect.CurrentTechnique.Passes)
        {
            pass.Apply();
            _device.DrawUserIndexedPrimitives(PrimitiveType.TriangleList,
                allVerts.ToArray(), 0, allVerts.Count, allIndices.ToArray(), 0, allIndices.Count / 3);
        }
    }

    private void DrawCriticalLine(TextureService textures)
    {
        _effect.Texture = textures.Get("criticalLine");
        float left = ArcFormula.LaneToWorldX(4) - 1f;
        float right = ArcFormula.LaneToWorldX(1) + 1f;
        float height = 0.3f;
        Color color = new Color(255, 255, 255, 230);

        var verts = new VertexPositionColorTexture[]
        {
            new(new Vector3(left, 0.02f, -height), color, new Vector2(0, 0)),
            new(new Vector3(right, 0.02f, -height), color, new Vector2(1, 0)),
            new(new Vector3(right, 0.02f, height), color, new Vector2(1, 1)),
            new(new Vector3(left, 0.02f, height), color, new Vector2(0, 1)),
        };
        var indices = new short[] { 0, 1, 2, 0, 2, 3 };

        foreach (var pass in _effect.CurrentTechnique.Passes)
        {
            pass.Apply();
            _device.DrawUserIndexedPrimitives(PrimitiveType.TriangleList, verts, 0, 4, indices, 0, 2);
        }
    }

    private void DrawBeatlines(TextureService textures, GameplayService gameplay)
    {
        if (gameplay.Chart == null) return;
        _effect.Texture = textures.Get("beatline");

        float left = ArcFormula.LaneToWorldX(4);
        float right = ArcFormula.LaneToWorldX(1);
        Color color = new Color(200, 200, 220, 80);
        float thickness = 0.08f;

        var tg = gameplay.Chart.TimingGroups[0];
        if (tg.Timings.Count == 0) return;

        var allVerts = new List<VertexPositionColorTexture>();
        var allIndices = new List<short>();

        foreach (var timing in tg.Timings)
        {
            if (timing.Bpm == 0 || timing.Divisor == 0) continue;
            float interval = 60000f / MathF.Abs(timing.Bpm) * timing.Divisor;
            if (interval < 1) continue;

            int nextTimingEnd = int.MaxValue;
            int tIdx = tg.Timings.IndexOf(timing);
            if (tIdx + 1 < tg.Timings.Count)
                nextTimingEnd = tg.Timings[tIdx + 1].Timing;

            for (float t = timing.Timing; t < nextTimingEnd; t += interval)
            {
                float z = gameplay.GetNoteZ(0, (int)t);
                if (!ArcFormula.WithinRenderRange(z)) continue;
                if (z > 5) continue;

                short offset = (short)allVerts.Count;
                allVerts.Add(new(new Vector3(left, 0.015f, z - thickness), color, new Vector2(0, 0)));
                allVerts.Add(new(new Vector3(right, 0.015f, z - thickness), color, new Vector2(1, 0)));
                allVerts.Add(new(new Vector3(right, 0.015f, z + thickness), color, new Vector2(1, 1)));
                allVerts.Add(new(new Vector3(left, 0.015f, z + thickness), color, new Vector2(0, 1)));
                allIndices.AddRange(new short[] { offset, (short)(offset + 1), (short)(offset + 2), offset, (short)(offset + 2), (short)(offset + 3) });

                if (allVerts.Count > 4000) break;
            }
            if (allVerts.Count > 4000) break;
        }

        if (allVerts.Count >= 4)
        {
            foreach (var pass in _effect.CurrentTechnique.Passes)
            {
                pass.Apply();
                _device.DrawUserIndexedPrimitives(PrimitiveType.TriangleList,
                    allVerts.ToArray(), 0, allVerts.Count, allIndices.ToArray(), 0, allIndices.Count / 3);
            }
        }
    }
}

