            new(new Vector3(left, 0.02f, height), color, new Vector2(0, 1)),
        };
        var indices = new short[] { 0, 1, 2, 0, 2, 3 };

        foreach (var pass in _effect.CurrentTechnique.Passes)
        {
            pass.Apply();
            _device.DrawUserIndexedPrimitives(PrimitiveType.TriangleList, verts, 0, 4, indices, 0, 2);
        }
    }

    private void DrawBeatlines(TextureService textures, GameplayService gameplay)
    {
        if (gameplay.Chart == null) return;
        _effect.Texture = textures.Get("beatline");

        float left = -TrackHalfWidth;
        float right = TrackHalfWidth;
        Color color = new Color(200, 200, 220, 80);
        float thickness = 0.08f;

        var tg = gameplay.Chart.TimingGroups[0];
        if (tg.Timings.Count == 0) return;

        var allVerts = new List<VertexPositionColorTexture>();
        var allIndices = new List<short>();

        foreach (var timing in tg.Timings)
        {
            if (timing.Bpm == 0 || timing.Divisor == 0) continue;
            float interval = 60000f / MathF.Abs(timing.Bpm) * timing.Divisor;
            if (interval < 1) continue;

            int nextTimingEnd = int.MaxValue;
            int tIdx = tg.Timings.IndexOf(timing);
            if (tIdx + 1 < tg.Timings.Count)
                nextTimingEnd = tg.Timings[tIdx + 1].Timing;

            for (float t = timing.Timing; t < nextTimingEnd; t += interval)
            {
                float z = gameplay.GetNoteZ(0, (int)t);
                if (!ArcFormula.WithinRenderRange(z)) continue;
                if (z > 5) continue;

                short offset = (short)allVerts.Count;
                allVerts.Add(new(new Vector3(left, 0.015f, z - thickness), color, new Vector2(0, 0)));
                allVerts.Add(new(new Vector3(right, 0.015f, z - thickness), color, new Vector2(1, 0)));
                allVerts.Add(new(new Vector3(right, 0.015f, z + thickness), color, new Vector2(1, 1)));
                allVerts.Add(new(new Vector3(left, 0.015f, z + thickness), color, new Vector2(0, 1)));
                allIndices.AddRange(new short[] { offset, (short)(offset + 1), (short)(offset + 2), offset, (short)(offset + 2), (short)(offset + 3) });

                if (allVerts.Count > 4000) break;
            }
            if (allVerts.Count > 4000) break;
        }

        if (allVerts.Count >= 4)
