namespace BetterArc.Gameplay;

public class AutoPlayScoring
{
    public int Score { get; private set; }
    public int Combo { get; private set; }
    public int MaxCombo { get; private set; }

    private int _totalNotes;
    private int _hitNotes;
    private const int MaxScore = 10_000_000;

    public void Initialize(GameplayService gameplay)
    {
        if (gameplay.Chart == null) return;

        _totalNotes = 0;
        foreach (var tg in gameplay.Chart.TimingGroups)
        {
            _totalNotes += tg.Taps.Count;
            _totalNotes += tg.Holds.Count;
            _totalNotes += tg.Arcs.Count(a => !a.IsTrace);
        }
    }

    public void UpdateToTiming(GameplayService gameplay, int currentTiming)
    {
        if (gameplay.Chart == null || _totalNotes == 0) return;

        int hitCount = 0;
        foreach (var tg in gameplay.Chart.TimingGroups)
        {
            hitCount += tg.Taps.Count(t => t.Timing <= currentTiming);
            hitCount += tg.Holds.Count(h => h.Timing <= currentTiming);
            hitCount += tg.Arcs.Count(a => !a.IsTrace && a.Timing <= currentTiming);
        }

        _hitNotes = hitCount;
        Combo = hitCount;
        MaxCombo = hitCount;

        if (_totalNotes > 0)
            Score = (int)((long)MaxScore * _hitNotes / _totalNotes);
    }
}

