internal class RenderBatchGame : Game
{
    private readonly GraphicsDeviceManager _graphics;
    private readonly string _chartText;
    private readonly List<(int timeMs, string refPath)> _timePoints;
    private readonly string _outputDir;

    private CameraService? _camera;
    private TextureService? _textures;
    private TrackRenderer? _track;
    private NoteRenderer? _notes;
    private GameplayService? _gameplay;
    private SpriteBatch? _spriteBatch;
    private RenderTarget2D? _renderTarget;
    private Color[]? _pixelBuffer;
    private int _frameIndex;
    private long _renderTicks, _readbackTicks, _encodeTicks;

    public RenderBatchGame(
        int width, int height, string chartText,
        List<(int timeMs, string refPath)> timePoints, string outputDir)
    {
        _chartText = chartText;
        _timePoints = timePoints;
        _outputDir = outputDir;

        _graphics = new GraphicsDeviceManager(this)
        {
            PreferredBackBufferWidth = width,
            PreferredBackBufferHeight = height,
            GraphicsProfile = GraphicsProfile.HiDef,
            SynchronizeWithVerticalRetrace = false,
        };

        IsMouseVisible = false;
        IsFixedTimeStep = false;
        TargetElapsedTime = TimeSpan.FromMilliseconds(1);
    }

    protected override void Initialize()
    {
        _camera = new CameraService();
        _textures = new TextureService();
        _textures.Initialize(GraphicsDevice);
        _track = new TrackRenderer(GraphicsDevice);
        _notes = new NoteRenderer(GraphicsDevice);
        _gameplay = new GameplayService();
        _gameplay.LoadChart(_chartText);
        _spriteBatch = new SpriteBatch(GraphicsDevice);

        int w = _graphics.PreferredBackBufferWidth;
        int h = _graphics.PreferredBackBufferHeight;
        _renderTarget = new RenderTarget2D(GraphicsDevice, w, h,
            false, SurfaceFormat.Color, DepthFormat.Depth24);
        _pixelBuffer = new Color[w * h];

        base.Initialize();
    }

    protected override void Draw(GameTime gameTime)
    {
        if (_frameIndex >= _timePoints.Count)
        {
            Exit();
            return;
        }

        var (timeMs, _) = _timePoints[_frameIndex];
        _gameplay!.CurrentTiming = timeMs;

        int w = _renderTarget!.Width;
        int h = _renderTarget.Height;

        long t0 = Stopwatch.GetTimestamp();

        GraphicsDevice.SetRenderTarget(_renderTarget);
        GraphicsDevice.Clear(new Color(49, 77, 121));

        var bgTex = _textures!.Has("background") ? _textures.Get("background") : null;
        if (bgTex != null)
        {
            _spriteBatch!.Begin(SpriteSortMode.Deferred, BlendState.Opaque);
            _spriteBatch.Draw(bgTex, new Microsoft.Xna.Framework.Rectangle(0, 0, w, h), Color.White);
            _spriteBatch.End();
        }

        GraphicsDevice.DepthStencilState = DepthStencilState.Default;
        _camera!.Update((float)w / h);
        _track!.Draw(_camera, _textures!, _gameplay);
        _notes!.Draw(_camera, _gameplay, _textures!);
        GraphicsDevice.SetRenderTarget(null);

        long t1 = Stopwatch.GetTimestamp();

        _renderTarget.GetData(_pixelBuffer);

        long t2 = Stopwatch.GetTimestamp();

        SavePng(_pixelBuffer!, w, h, Path.Combine(_outputDir,
            $"actual_t{VisualTestBase.FormatTime(timeMs)}.png"));

        long t3 = Stopwatch.GetTimestamp();

        _renderTicks += t1 - t0;
        _readbackTicks += t2 - t1;
        _encodeTicks += t3 - t2;
        _frameIndex++;

        if (_frameIndex % 20 == 0 || _frameIndex == _timePoints.Count)
        {
            double renderMs = _renderTicks * 1000.0 / Stopwatch.Frequency;
            double readbackMs = _readbackTicks * 1000.0 / Stopwatch.Frequency;
            double encodeMs = _encodeTicks * 1000.0 / Stopwatch.Frequency;
            Console.Error.WriteLine(
                $"[L2] {_frameIndex}/{_timePoints.Count} (t={timeMs}ms) " +
                $"render={renderMs:F0}ms readback={readbackMs:F0}ms encode={encodeMs:F0}ms");
        }

        if (_frameIndex >= _timePoints.Count)
            Exit();

        base.Draw(gameTime);
    }

    private static readonly SixLabors.ImageSharp.Formats.Png.PngEncoder FastPng = new()
    {
        CompressionLevel = SixLabors.ImageSharp.Formats.Png.PngCompressionLevel.BestSpeed,
    };

    private static void SavePng(Color[] pixels, int w, int h, string path)
    {
        using var img = new Image<Rgba32>(w, h);
        for (int y = 0; y < h; y++)
        {
            var row = img.Frames.RootFrame.PixelBuffer.DangerousGetRowSpan(y);
            for (int x = 0; x < w; x++)
            {
                var c = pixels[y * w + x];
                row[x] = new Rgba32(c.R, c.G, c.B, c.A);
            }
        }
        img.Save(path, FastPng);
    }

    protected override void Dispose(bool disposing)
    {
        _renderTarget?.Dispose();
        base.Dispose(disposing);
    }
}

