    public void Initialize(TextureService textures)
    {
        _spriteBatch = new SpriteBatch(_device);
        _pixel = new Texture2D(_device, 1, 1);
        _pixel.SetData(new[] { Color.White });

        string? assetsBase = textures.GetAssetsBasePath();
        if (assetsBase == null) return;

        string fontsDir = Path.Combine(assetsBase, "fonts");

        // Two separate FontSystems so we can pick Regular vs Medium
        _fontRegular = new FontSystem();
        _fontMedium = new FontSystem();

        string sairaRegular = Path.Combine(fontsDir, "Saira-Regular.ttf");
