using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using FontStashSharp;

namespace BetterArc.Render;

public class UIRenderer
{
    private readonly GraphicsDevice _device;
    private SpriteBatch? _spriteBatch;
    private FontSystem? _fontRegular;
    private FontSystem? _fontMedium;
    private Texture2D? _jacket;
    private Texture2D? _pixel;

    // --- All constants derived from Gameplay.unity RectTransform data ---
    // InfoPanel: anchor(1,1), pivot(1,1), pos(0,-16), size(681,350), scale(0.5,0.5)
    private const int PanelX = 940;   // 1280 - 681*0.5
    private const int PanelY = 16;    // 720 - (720 + (-16)) → 16
    private const int PanelW = 340;   // 681 * 0.5
    private const int PanelH = 175;   // 350 * 0.5

    // JacketBackground: anchor(0.5,0.5), pivot(0.5,1), pos(-300,124), size(235,285)
    private const int JacketBgX = 901;  // 940 + (-77)*0.5
    private const int JacketBgY = 42;   // 16 + (350-299)*0.5
    private const int JacketBgW = 118;  // 235 * 0.5
    private const int JacketBgH = 143;  // 285 * 0.5

    // JacketImage: fill parent, offsetMin(17,67), offsetMax(-17,-17) → 201×201
    private const int JacketX = 910;    // 901 + 17*0.5
    private const int JacketY = 50;     // 42 + (285-268)*0.5
    private const int JacketSize = 101; // 201 * 0.5

    // DifficultyImage: anchor bottom(0,0)-(1,0), pivot(0.5,1), pos(0,67), size(-34,51)
    private const int DiffX = 910;      // 901 + 17*0.5
    private const int DiffY = 151;      // 42 + (285-67)*0.5
    private const int DiffW = 101;      // 201 * 0.5
    private const int DiffH = 26;       // 51 * 0.5
    // DifficultyImage bg: RGBA(0.282, 0.169, 0.329, 1)
    private static readonly Color DiffBgColor = new(72, 43, 84, 255);

    // ScoreLabel: anchor(0,0.5)-(1,0.5), pivot(0,1), pos(185,145), fontSize=25
    private const int ScoreLabelX = 1033; // 940 + 185*0.5
    private const int ScoreLabelY = 31;   // 16 + (350-320)*0.5
    private const float ScoreLabelFontSize = 13f; // 25 * 0.5

    // ScoreText: anchor(0,0.5)-(1,0.5), pivot(0,1), pos(180,110), fontSize=87
    private const int ScoreTextX = 1030;  // 940 + 180*0.5
    private const int ScoreTextY = 49;    // 16 + (350-285)*0.5
    private const float ScoreTextFontSize = 44f; // 87 * 0.5

    // TitleText: anchor(0,1)-(1,1), pivot(0,1), pos(185,-190), fontSize auto max 45
    private const int TitleX = 1033;      // 940 + 185*0.5
    private const int TitleY = 111;       // 16 + (350-160)*0.5
    private const float TitleFontSize = 22f; // 45 * 0.5 (auto-size max)

    // ComposerText: anchor(0,1)-(1,1), pivot(0,0), pos(185,-320), fontSize auto max 30
    private const int ComposerX = 1033;   // 940 + 185*0.5
    private const int ComposerY = 146;    // 16 + (350-90)*0.5
    private const float ComposerFontSize = 15f; // 30 * 0.5

    // PauseButton: anchor(0,1), pivot(0,1), pos(-118,-23), size(237.33,99), scale(1,1,1)
    private const int PauseX = -118;
    private const int PauseY = 23;        // 720-(720+(-23))
    private const int PauseW = 237;       // 237.33
    private const int PauseH = 99;

    // ComboText: anchor(0.5,0.5), pivot(0.5,0.5), pos(0,-40), fontSize=90
    private const int ComboCenterY = 400; // 720-(720*0.5+(-40))
    private const float ComboFontSize = 90f;
    // RGBA(0.47058824, 0.23529412, 0.47058824, 0.8)
    private static readonly Color ComboColor = new(120, 60, 120, 204);

    public UIRenderer(GraphicsDevice device)
    {
        _device = device;
    }

    public void Initialize(TextureService textures)
    {
        _spriteBatch = new SpriteBatch(_device);
        _pixel = new Texture2D(_device, 1, 1);
        _pixel.SetData(new[] { Color.White });

        string? assetsBase = textures.GetAssetsBasePath();
        if (assetsBase == null) return;

        string fontsDir = Path.Combine(assetsBase, "fonts");

        _fontRegular = new FontSystem();
        _fontMedium = new FontSystem();

        string sairaRegular = Path.Combine(fontsDir, "Saira-Regular.ttf");
        string sairaMedium = Path.Combine(fontsDir, "Saira-Medium.ttf");
        if (File.Exists(sairaRegular))
            _fontRegular.AddFont(File.ReadAllBytes(sairaRegular));
        if (File.Exists(sairaMedium))
            _fontMedium.AddFont(File.ReadAllBytes(sairaMedium));
    }

    public void LoadJacket(GraphicsDevice device, string path)
    {
        if (!File.Exists(path)) return;
        using var stream = File.OpenRead(path);
        _jacket = Texture2D.FromStream(device, stream);
    }

    public void Draw(TextureService textures, int score, int combo,
        string title, string composer, string difficulty)
    {
        if (_spriteBatch == null) return;

        _spriteBatch.Begin(SpriteSortMode.Deferred, BlendState.AlphaBlend);

        DrawPauseButton(textures);
        DrawInfoPanel(textures, score, title, composer, difficulty);
        if (combo > 0)
            DrawCombo(combo);

        _spriteBatch.End();
    }

    private void DrawInfoPanel(TextureService textures, int score,
        string title, string composer, string difficulty)
    {
        if (textures.Has("hudInfo"))
            _spriteBatch!.Draw(textures.Get("hudInfo"),
                new Rectangle(PanelX, PanelY, PanelW, PanelH), Color.White);

        if (textures.Has("hudJacketBg"))
            _spriteBatch!.Draw(textures.Get("hudJacketBg"),
                new Rectangle(JacketBgX, JacketBgY, JacketBgW, JacketBgH), Color.White);

        if (_jacket != null)
            _spriteBatch!.Draw(_jacket,
                new Rectangle(JacketX, JacketY, JacketSize, JacketSize), Color.White);

        if (_pixel != null)
            _spriteBatch!.Draw(_pixel,
                new Rectangle(DiffX, DiffY, DiffW, DiffH), DiffBgColor);

        if (difficulty.Length > 0 && _fontMedium != null)
        {
            var font = _fontMedium.GetFont(DiffH - 4);
            _spriteBatch!.DrawString(font, difficulty,
                new Vector2(DiffX + 4, DiffY + 2), Color.White);
        }

        if (_fontMedium != null)
        {
            var font = _fontMedium.GetFont(ScoreLabelFontSize);
            _spriteBatch!.DrawString(font, "SCORE:",
                new Vector2(ScoreLabelX, ScoreLabelY), Color.White);
        }

        if (_fontRegular != null)
        {
            var font = _fontRegular.GetFont(ScoreTextFontSize);
            string scoreText = score.ToString("D8");
            _spriteBatch!.DrawString(font, scoreText,
                new Vector2(ScoreTextX, ScoreTextY), Color.White);
        }

        if (_fontMedium != null)
        {
            var font = _fontMedium.GetFont(TitleFontSize);
            _spriteBatch!.DrawString(font, title,
                new Vector2(TitleX, TitleY), Color.White);
        }

        if (_fontRegular != null)
        {
            var font = _fontRegular.GetFont(ComposerFontSize);
            _spriteBatch!.DrawString(font, composer,
                new Vector2(ComposerX, ComposerY), Color.White);
        }
    }

    private void DrawPauseButton(TextureService textures)
    {
        if (!textures.Has("hudPause")) return;

        var tex = textures.Get("hudPause");
        _spriteBatch!.Draw(tex,
            new Rectangle(PauseX, PauseY, PauseW, PauseH), Color.White);
    }

    private void DrawCombo(int combo)
    {
        if (_fontRegular == null || _spriteBatch == null) return;

        var font = _fontRegular.GetFont(ComboFontSize);
        string text = combo.ToString();
        var size = font.MeasureString(text);
        float x = (1280 - size.X) / 2;
        float y = ComboCenterY - size.Y / 2;

        _spriteBatch.DrawString(font, text, new Vector2(x, y), ComboColor);
    }
}

