using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using FontStashSharp;

namespace BetterArc.Render;

public class UIRenderer
{
    private readonly GraphicsDevice _device;
    private SpriteBatch? _spriteBatch;
    private FontSystem? _fontSystem;
    private SpriteFontBase? _fontScore;
    private SpriteFontBase? _fontScoreLabel;
    private SpriteFontBase? _fontTitle;
    private SpriteFontBase? _fontComposer;
    private SpriteFontBase? _fontDifficulty;
    private SpriteFontBase? _fontCombo;
    private Texture2D? _jacket;

    public UIRenderer(GraphicsDevice device)
    {
        _device = device;
    }

    public void Initialize(TextureService textures)
    {
        _spriteBatch = new SpriteBatch(_device);

        string? assetsBase = textures.GetAssetsBasePath();
        if (assetsBase == null) return;

        string fontsDir = Path.Combine(assetsBase, "fonts");
        _fontSystem = new FontSystem();

        string sairaRegular = Path.Combine(fontsDir, "Saira-Regular.ttf");
        string sairaMedium = Path.Combine(fontsDir, "Saira-Medium.ttf");
        if (File.Exists(sairaRegular))
            _fontSystem.AddFont(File.ReadAllBytes(sairaRegular));
        if (File.Exists(sairaMedium))
            _fontSystem.AddFont(File.ReadAllBytes(sairaMedium));

        _fontScoreLabel = _fontSystem.GetFont(11);
        _fontScore = _fontSystem.GetFont(38);
        _fontTitle = _fontSystem.GetFont(14);
        _fontComposer = _fontSystem.GetFont(10);
        _fontDifficulty = _fontSystem.GetFont(10);
        _fontCombo = _fontSystem.GetFont(90);
    }

    public void LoadJacket(GraphicsDevice device, string path)
    {
        if (!File.Exists(path)) return;
        using var stream = File.OpenRead(path);
        _jacket = Texture2D.FromStream(device, stream);
    }

    public void Draw(TextureService textures, int score, int combo,
        string title, string composer, string difficulty)
    {
        if (_spriteBatch == null) return;

        _spriteBatch.Begin(SpriteSortMode.Deferred, BlendState.AlphaBlend);

        DrawInfoPanel(textures, score, title, composer, difficulty);
        DrawPauseButton(textures);
        if (combo > 0)
            DrawCombo(combo);

        _spriteBatch.End();
    }

    private void DrawInfoPanel(TextureService textures, int score,
        string title, string composer, string difficulty)
    {
        // Matched from reference frame pixel analysis:
        // Panel background: top-right, with jacket on left and text on right
        int panelW = 340;
        int panelH = 105;
        int panelX = 1280 - panelW;
        int panelY = 8;

        // Panel background
        if (textures.Has("hudInfo"))
        {
            _spriteBatch!.Draw(textures.Get("hudInfo"),
                new Rectangle(panelX, panelY, panelW, panelH), Color.White);
        }

        // Jacket artwork (left side of panel)
        int jacketSize = 80;
        int jacketX = panelX + 5;
        int jacketY = panelY + 5;
        if (_jacket != null)
        {
            _spriteBatch!.Draw(_jacket,
                new Rectangle(jacketX, jacketY, jacketSize, jacketSize), Color.White);
        }

        // Text column starts after jacket
        int textX = panelX + jacketSize + 12;

        // "SCORE:" label
        if (_fontScoreLabel != null)
            _spriteBatch!.DrawString(_fontScoreLabel, "SCORE:",
                new Vector2(textX, panelY + 3), Color.White);

        // Score number
        if (_fontScore != null)
        {
            string scoreText = score.ToString("D8");
            _spriteBatch!.DrawString(_fontScore, scoreText,
                new Vector2(textX, panelY + 14), Color.White);
        }

        // Chart title
        if (_fontTitle != null)
            _spriteBatch!.DrawString(_fontTitle, title,
                new Vector2(textX, panelY + 58), Color.White);

        // Difficulty badge (below jacket)
        if (difficulty.Length > 0)
        {
            if (_fontDifficulty != null)
                _spriteBatch!.DrawString(_fontDifficulty, difficulty,
                    new Vector2(jacketX + 2, jacketY + jacketSize + 2), Color.White);
        }

        // Composer/artist
        if (_fontComposer != null)
            _spriteBatch!.DrawString(_fontComposer, composer,
                new Vector2(textX, panelY + 78), Color.White);
    }

    private void DrawPauseButton(TextureService textures)
    {
        if (!textures.Has("hudPause")) return;

        // Pause button: top-left, partially off-screen
        // ArcCreate: pos(-118,-23), size(237.33, 99) → visible from x=0
        int btnW = 119;
        int btnH = 50;
        int btnX = 0;
        int btnY = 12;

        // Draw the right portion of the pause texture (left half is off-screen)
        var srcRect = new Rectangle(
            textures.Get("hudPause").Width / 2, 0,
            textures.Get("hudPause").Width / 2, textures.Get("hudPause").Height);
        _spriteBatch!.Draw(textures.Get("hudPause"),
            new Rectangle(btnX, btnY, btnW, btnH), srcRect, Color.White);
    }

    private void DrawCombo(int combo)
    {
        if (_fontCombo == null || _spriteBatch == null) return;

        string comboText = combo.ToString();
        var size = _fontCombo.MeasureString(comboText);
        float x = (1280 - size.X) / 2;
        float y = 320 - size.Y;

        var comboColor = new Color(120, 61, 120, 204);
        _spriteBatch.DrawString(_fontCombo, comboText, new Vector2(x, y), comboColor);
    }
}
